// Safely extract and format AI output for FeedBox API
const item = $input.first().json;
let parsed = {};

if (item.output && typeof item.output === 'object') {
  parsed = item.output;
} else if (item.response && typeof item.response === 'object') {
  parsed = item.response;
} else if (typeof item.text === 'string') {
  try {
    const cleaned = item.text.replace(/```json/gi, '').replace(/```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = { summary: item.text };
  }
} else {
  parsed = item;
}

return [{
  json: {
    category: parsed.category || 'Issue',
    urgency: parsed.urgency || 'Medium',
    summary: parsed.summary || 'Maintenance report received',
    location: parsed.location || null,
    department: parsed.department || 'Maintenance',
    problem: parsed.problem || 'Needs inspection',
    suggested_action: parsed.suggested_action || null,
    confidence: parsed.confidence || 0.96,
    source: 'n8n_groq_agent',
    processed_at: new Date().toISOString()
  }
}];
